'use strict';

// MODULES //

var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var format = require( '@stdlib/string/format' );
var startsWith = require( '@stdlib/string/starts-with' );
var SocketBase = require( './base.js' );
var Message = require( './../message/main.js' );
var log = require( './../custom_log.js' );


// FUNCTIONS //

/**
* Parses a signature scheme name.
*
* @private
* @param {string} scheme - unparsed scheme name
* @throws {TypeError} must provide a supported scheme
* @returns {string} scheme
*/
function parseScheme( scheme ) {
	if ( !startsWith( scheme, 'hmac-' ) ) {
		throw new TypeError( format( 'invalid argument. `signature_scheme` must be a supported scheme. Value: `%s`.', scheme ) );
	}
	return scheme.split( '-' )[ 1 ];
}


// MAIN //

/**
* Socket constructor.
*
* @private
* @constructor
* @param {string} type - socket type
* @param {string} ip - client address
* @param {number} port - client port
* @param {string} transport - protocol name
* @param {string} scheme - signature scheme
* @param {string} key - signature key
* @returns {Socket} socket instance
*/
function Socket( type, ip, port, transport, scheme, key ) {
	if ( !( this instanceof Socket ) ) {
		return new Socket( type, ip, port, transport, scheme, key );
	}

	// Call the parent constructor:
	SocketBase.call( this, type, ip, port, transport );

	// Signature:
	this._scheme = parseScheme( scheme );
	this._key = key;

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Socket, SocketBase );

/**
* Initializes message listener on the socket.
*
* @private
* @name listen
* @memberof Socket.prototype
* @type {Function}
* @returns {void}
*/
setNonEnumerableReadOnly( Socket.prototype, 'listen', function listen() {
	var self;

	// Call the parent method:
	SocketBase.prototype.listen.call( this );

	self = this;
	this.on( 'message', onMessage );

	/**
	* Callback invoked upon receiving a "message" event.
	*
	* @private
	* @param {Array<Buffer>} message - raw message frames
	* @returns {void}
	*/
	function onMessage( message ) {
		message = Message.decode( message, self._scheme, self._key );
		if ( message instanceof TypeError ) {
			return;
		}
		self.emit( 'request', message );
	}
});

/**
* Sends a message over the zmq socket.
*
* @private
* @name send
* @memberof Socket.prototype
* @type {Function}
* @param {Message} message - message
* @returns {void}
*/
setNonEnumerableReadOnly( Socket.prototype, 'send', function send( message ) {
	log( JSON.stringify( message ) );
	SocketBase.prototype.send.call( this, message.encode( this._scheme, this._key ) );
});

// TODO: add methods for graceful closing.


// EXPORTS //

module.exports = Socket;
